const e=JSON.parse(`{"lindenau-visite-etat":{"hook":"“Mr President, I have entered a state visit in my diary, section 4, paragraph b.”","news":"Chancellor Lindenau announces a state visit, backed by a 47-page programme","scene":{"intro":"Lindenau has sent a forty-seven-page visit programme, timed toilet breaks included.","nodes":{"n1":{"text":"I would come with forty advisers, a spreadsheet and my own pen. Will you receive me, in due and proper form?","choices":[{"label":"Gladly accept the state visit","reponsePresident":"With great pleasure, Hartmut: do come, and bring your pen."},{"label":"Politely decline: the quarter’s diary is full","reponsePresident":"I am sorry, Hartmut: my diary for the quarter is full to bursting."}]},"n2":{"text":"The chancellor notes your answer in his little black notebook, then asks how to present it to the press.","choices":[{"label":"A sober communiqué, in two languages","reponsePresident":"A sober communiqué, in two languages. Nothing more, and that is already plenty."},{"label":"A festive announcement with brass band and sausages","reponsePresident":"Let us make a joyful announcement: brass band, sausages, and everyone smiling!"}]}}},"motif":"Lindenau offers to come to Paris on a state visit next quarter."},"lindenau-gaz-hiver":{"hook":"“Mr President, my factories are shivering and so is my spreadsheet. Could you lend a few electrons?”","news":"Berlin asks Paris for an electric helping hand","scene":{"intro":"Down the line you can hear the click of an overheating spreadsheet. Lindenau speaks like someone reading an emergency bulletin.","nodes":{"n1":{"text":"I’m not asking for charity. I’m asking for an emergency contract, three copies, at a reasonable interest rate.","choices":[{"label":"Supply the electricity at full price","reponsePresident":"I will supply the electricity at full price, Hartmut: that is the market."},{"label":"Supply it at cost, in solidarity","reponsePresident":"I will supply it at cost. Between neighbours, we keep warm together."},{"label":"Reply that France must first heat the French","reponsePresident":"I must first heat the French, Hartmut. After that, we shall see."}]},"n2":{"text":"In return, I will support your position on the budget calendar. A little. In a footnote.","choices":[{"label":"Accept the footnote","reponsePresident":"The footnote it is, then. I accept."},{"label":"Demand better than a footnote","reponsePresident":"A footnote? No, I demand better than that."}]}}},"motif":"Lindenau asks for emergency electricity to get through the energy crisis."},"lindenau-deficit-plainte":{"hook":"“Mr President, your deficits keep me awake. I counted them three times; they went up three times.”","news":"Berlin alarmed at French accounts: “I counted them three times”","scene":{"intro":"The chancellor calls with a chart. You can hear him unrolling it, even over the phone.","nodes":{"n1":{"text":"My Parliament is wondering. My electorate is wondering. My spreadsheet is no longer wondering: it is worried.","choices":[{"label":"Commit to a deficit-reduction path","reponsePresident":"I commit to a deficit-reduction path, Hartmut."},{"label":"Point out that Berlin bends the rules too","reponsePresident":"Berlin bends the rules too, Hartmut. We both know it."},{"label":"Propose a cross-audit of the accounts","reponsePresident":"I propose a cross-audit: your accounts against ours, in full transparency."}]},"n2":{"text":"In that case, I want a progress report every quarter. In person, with a projector.","choices":[{"label":"Accept the quarterly progress report","reponsePresident":"I accept a progress report every quarter, bound and signed."},{"label":"Negotiate a progress report by email","reponsePresident":"A progress report by email would suit me better, Hartmut."}]}}},"motif":"Lindenau complains about French deficits and demands rigour."},"lindenau-tableur-trimestre":{"hook":"“Good day, Mr President. Rest assured, this is not urgent. It is merely important, and scheduled.”","news":"Paris and Berlin hold their quarterly review, spreadsheet in hand","scene":{"intro":"The chancellor blocked this slot six months ago. He reminds you of it in a warm tone, for a spreadsheet.","nodes":{"n1":{"text":"I have synchronised our European diaries. You will note that I placed your lunch at twelve-twelve, out of consideration.","choices":[{"label":"Approve the joint calendar","reponsePresident":"I approve the joint calendar, Hartmut. Box ticked."},{"label":"Offer to move a meeting in France’s favour","reponsePresident":"I propose moving one meeting, in France's favour, naturally."}]},"n2":{"text":"Last point: a sheet of joint commitments. It has fourteen columns, one of them in reserve.","choices":[{"label":"Sign it without reading it all","reponsePresident":"I will sign it, Hartmut. I trust you on the small print."},{"label":"Add a “French ambitions” column","reponsePresident":"I am adding a “French ambitions” column. It will be very full."},{"label":"Ask for a one-page summary","reponsePresident":"Could you give me a one-page summary, Hartmut? Just one."}]}}},"motif":"Lindenau calls for his quarterly Franco-German coordination review."},"lindenau-felicitations-export":{"hook":"“My economists checked your figures three times. They are good. Congratulations, and I am almost annoyed.”","news":"Lindenau congratulates Paris: “Almost German figures”","scene":{"intro":"The chancellor calls for the first time without asking for anything. You check that the line isn’t tapped.","nodes":{"n1":{"text":"Your results worry me for my market share and delight me for Europe. I have put an asterisk.","choices":[{"label":"Thank him with humility","reponsePresident":"Thank you, Hartmut, with all the humility I can muster."},{"label":"Joke: “We learn from you”","reponsePresident":"We learn from you, Hartmut. Mostly how to fill in a spreadsheet."},{"label":"Boast loudly","reponsePresident":"Yes, we are excellent, and I say it loud and clear!"}]},"n2":{"text":"Since all is well: a little joint project? I say “little” out of politeness.","choices":[{"label":"Launch a joint study on industry","reponsePresident":"Let us launch a joint study on industry, Hartmut."},{"label":"Put it off until later","reponsePresident":"Let us put that off until later, Hartmut, if you do not mind."}]}}},"motif":"Lindenau congratulates France on its good results."},"lindenau-sommet-declaration":{"hook":"“A summit is coming. I have prepared a draft joint declaration; rest assured, it runs to only eleven pages.”","news":"Before the summit, Berlin and Paris polish an “eleven-page” declaration","scene":{"intro":"The chancellor has already printed the final communiqué. The date of the summit, however, is still vague.","nodes":{"n1":{"text":"I propose that we speak with one voice. Mine, preferably, but I am flexible on the accent.","choices":[{"label":"Accept a joint text, drafted in equal parts","reponsePresident":"I accept a joint text, drafted in equal parts, word for word."},{"label":"Defend a more ambitious French position","reponsePresident":"France will defend a more ambitious position, Hartmut."}]},"n2":{"text":"And the energy item? I wouldn’t dare forget it. I highlighted it in three colours.","choices":[{"label":"Defend a joint energy clause","reponsePresident":"I defend a joint energy clause, Hartmut: it is in all our interests."},{"label":"Push for a stronger climate chapter","reponsePresident":"I am pushing for a stronger climate chapter. The planet will not wait."},{"label":"Avoid the subject","reponsePresident":"Let us avoid the subject, Hartmut. On to dessert."}]}}},"motif":"Lindenau wants to coordinate his position with France before the summit."},"lindenau-appel-electricite":{"hook":"“I have an electricity proposal, a file and a sausage. I invite you to the Chancellery.”","news":"Lindenau invites Paris to talk electricity: 212-page file","motif":"Lindenau wants to seal a deal on French nuclear electricity.","phone":{"intro":"Down the line, you can hear Lindenau turning the pages of a 212-page file on electricity interconnections. He sums it up in one sentence: “You have nuclear, I have factories.”","nodes":{"n3":{"labels":{"0":"Seal the deal and hang up"}}}}},"lindenau-appel-industrie":{"hook":"“Europe is losing ground, Mr President. I propose a lunch, a fund and a sausage.”","news":"Berlin proposes a European fund for batteries","motif":"Lindenau proposes a European fund for batteries and industry.","phone":{"intro":"Lindenau calls from a restaurant strictly compliant with DIN standards: you can hear him lining up his cutlery. On the menu: European competitiveness, plus a sausage.","nodes":{"n3":{"text":"Down the line, you can hear the chancellor noting everything in a little black-covered notebook. Nobody knows what he writes there, but the mood has cooled or warmed by three degrees.","labels":{"1":"Hang up without a communiqué, out of sheer pride"}}}}},"whitcombe-visite-etat":{"hook":"“Mr President! I’m coming to see you, with my delegation, my plane and my little flags.”","news":"Whitcombe announces his visit to Paris: “It’s going to be huge”","scene":{"intro":"Whitcombe announces his visit the way you announce a promotion: with confetti in his voice.","nodes":{"n1":{"text":"Deal? I come on a state visit, you give me a banquet, and we sign things. Lots of things.","choices":[{"label":"Accept the state visit"},{"label":"Politely decline: diary too full"}]},"n2":{"text":"Whitcombe is already asking whether the banquet will include “refined” hamburgers.","choices":[{"label":"Plan a Franco-American menu"},{"label":"Stick to French gastronomy"}]}}},"motif":"Whitcombe offers to come to Paris on a state visit next quarter."},"whitcombe-condoleances":{"hook":"“Mr President, America is with you. So is my team, and even the White House dog.”","news":"Washington offers its condolences to France","scene":{"intro":"Whitcombe has put his smile away for the call. All that’s left is a small standby light.","nodes":{"n1":{"text":"I’m calling with no agenda, no deal. Just to say that we share your grief.","choices":[{"label":"Simply thank him and accept his support"},{"label":"Propose a joint tribute, side by side"},{"label":"Decline the help to show your independence"}]},"n2":{"text":"If you need teams, resources, or a very large coffee, just say so.","choices":[{"label":"Accept relief cooperation"},{"label":"Thank him warmly and decline"}]}}},"motif":"Whitcombe offers his condolences and his help after the tragedy."},"whitcombe-menace-douanes":{"hook":"“My advisers are talking about 25% tariffs. Me, I’d prefer a deal. For now.”","news":"Washington brandishes tariffs: “A deal, or else…”","scene":{"intro":"You can hear Whitcombe’s smile over the phone, but it’s a negotiating smile.","nodes":{"n1":{"text":"Your cheeses come into our country too easily, our planes into yours too rarely. We’ll need to rebalance.","choices":[{"label":"Propose a reciprocity agreement"},{"label":"Brandish European reprisals"},{"label":"Offer a plane purchase in exchange for the status quo"}]},"n2":{"text":"I’m reasonable. I’m even very reasonable. I just have bigger numbers than yours.","choices":[{"label":"Accept a schedule of talks"},{"label":"Demand arbitration by the trade organisation"}]}}},"motif":"Whitcombe threatens to raise tariffs if France doesn’t give in."},"whitcombe-gaz-mais":{"hook":"“Mr President, I have gas, corn and planes. And a special package just for you.”","news":"Washington offers Paris a gas, corn and plane bundle","scene":{"intro":"Whitcombe opens the call like an in-store promotion: “Today only!”","nodes":{"n1":{"text":"I offer you a bundle: liquefied gas, corn, planes. Packaging on the house.","choices":[{"label":"Take the gas only"},{"label":"Take the planes only"},{"label":"Decline the whole bundle"}]},"n2":{"text":"What if I cut the price by 3%? I’m even cutting the price of my good mood.","choices":[{"label":"Haggle for an industrial counterpart"},{"label":"Accept the discount unconditionally"}]}}},"motif":"Whitcombe wants to sell you gas, corn and planes."},"whitcombe-appui-guerre":{"hook":"“You’re at war, Mr President? Then I have satellites, advisers and invoices.”","news":"Washington offers military support: the bill will follow","scene":{"intro":"Whitcombe speaks in a reassuring tone, like an insurance salesman beside a fire.","nodes":{"n1":{"text":"I offer you satellite intelligence, logistics and air support. Friend’s price, which is thirty per cent more.","choices":[{"label":"Accept the intelligence only"},{"label":"Accept the whole package"},{"label":"Refuse: France will manage"}]},"n2":{"text":"Shall we meet for a debrief? My teams have already booked the rooms. And the coffee.","choices":[{"label":"Accept a joint debrief"},{"label":"Propose a remote debrief"}]}}},"motif":"Whitcombe offers military support to France at war, subject to signature."},"whitcombe-felicitations-victoire":{"hook":"“Congratulations, Mr President! I told everyone here, including the switchboard operator.”","news":"Whitcombe congratulates France: “We watched on three screens”","scene":{"intro":"Whitcombe calls with background noise: it sounds like a stadium, or a buffet.","nodes":{"n1":{"text":"What a performance! Over here we watched on three screens. My son shouted, I think it was for your team.","choices":[{"label":"Joke about a friendly bet"},{"label":"Invite him to a future match"},{"label":"Thank him coldly, nothing more"}]},"n2":{"text":"One day we’ll do a deal on TV rights. That’s my dream, somewhere between the gas and the planes.","choices":[{"label":"Mention a cultural co-production"},{"label":"Elegantly dodge"}]}}},"motif":"Whitcombe congratulates France on its sporting success."},"whitcombe-appel-renseignement":{"hook":"“Mr President, my services are bored. Yours too, I suppose. Let’s team up!”","news":"Whitcombe wants shared intelligence: “Everyone will smile”","motif":"Whitcombe proposes sharing wiretaps between intelligence services.","phone":{"intro":"Whitcombe calls from the Oval Office; his voice echoes as if in front of one flag per donor. He brags about his coffee “as big as a bucket”: “You are going to love our cooperation.”","nodes":{"n3":{"labels":{"0":"Propose a joint communiqué, no photo"}}}}},"whitcombe-appel-defense":{"hook":"“You spend little on your defence, Mr President. But I have very convincing catalogues.”","news":"Washington presses Paris to spend more on defence","motif":"Whitcombe asks France to strengthen its defence budget.","phone":{"intro":"Whitcombe calls you from a military base for “a quick spin in the simulator”: jet engines roar in the background. You quickly realise you are being sold something.","nodes":{"n3":{"text":"Whitcombe announces he is sending an autographed pilot's helmet. Impossible to refuse without a diplomatic incident, or to wear without a compromising photo.","labels":{"0":"Accept the autographed helmet"}}}}},"oakhaven-plainte-peche":{"hook":"“Mr President, our fishermen find your inspections ‘interesting’. Where we come from, that’s a battle cry.”","news":"London protests: British trawlers held, cold tea at Whitehall","scene":{"intro":"Oakhaven looks like a man gripping his cup slightly harder than usual.","nodes":{"n1":{"text":"A few trawlers have been detained. We are very calm, naturally. Calm as a kettle.","choices":[{"label":"Promise a swift inquiry"},{"label":"Firmly defend your inspections"},{"label":"Propose a joint fisheries committee"}]},"n2":{"text":"Interesting. I note that we agree, or almost, or not at all.","choices":[{"label":"Propose temporary licences"},{"label":"Conclude with an empty communiqué"}]}}},"motif":"Oakhaven complains about British fishermen’s access to French waters."},"oakhaven-visite-etat":{"hook":"“I am thinking of coming to see you, Mr President. A state visit, a tea, and two carefully weighed compliments.”","news":"Sir Oakhaven-Lowe expected in Paris: “An interesting visit”","scene":{"intro":"Oakhaven mentions his coming with the enthusiasm of a friendly tax audit.","nodes":{"n1":{"text":"A state visit would be… interesting. We might even smile in public, provided the lighting is good.","choices":[{"label":"Accept the state visit"},{"label":"Politely decline, citing the calendar"}]},"n2":{"text":"Oakhaven asks whether the protocol provides for tea, or a “moment of conviviality”. He has already checked both.","choices":[{"label":"Plan tea and champagne"},{"label":"Opt for a sober ceremony"}]}}},"motif":"Oakhaven offers to come to Paris on a state visit next quarter."},"oakhaven-sommet-marge":{"hook":"“A summit, Mr President? Charming. I shall attend with a communiqué already drafted, but open to suggestions.”","news":"London and Paris to meet on the margins of the summit, “discreetly”","scene":{"intro":"Oakhaven speaks like someone drafting a staff memo: carefully, and without saying anything specific.","nodes":{"n1":{"text":"I propose a meeting on the sidelines. Discreet. So discreet that our two delegations won’t see each other.","choices":[{"label":"Accept the discreet meeting"},{"label":"Demand a public photo"}]},"n2":{"text":"Let’s talk finance, migration, fishing. In that order, or another.","choices":[{"label":"Put migration first"},{"label":"Put finance first"},{"label":"Keep fishing for last"}]}}},"motif":"Oakhaven proposes a meeting on the margins of the summit."},"oakhaven-renseignement-cyber":{"hook":"“Mr President, would you have five minutes and a secure line? What I am about to say will not exist.”","news":"Did London and Paris talk cyber? Nobody confirms","scene":{"intro":"Oakhaven’s voice drops a notch, which, for him, equals a shout.","nodes":{"n1":{"text":"Our services have seen things on the networks. We would like to share them. Without telling anyone, obviously.","choices":[{"label":"Accept a supervised sharing, declared to Parliament"},{"label":"Accept full and discreet sharing","secret":{"leakNews":"FLASH — Paris and London reportedly share cyber data in secret, according to internal documents"}},{"label":"Refuse: cybersecurity is a national matter"}]},"n2":{"text":"Perfect. I shall send you a code, a second code, and a biscuit.","choices":[{"label":"Take the biscuit and the codes"},{"label":"Ask for written proof of reciprocity"}]}}},"motif":"Oakhaven proposes a discreet exchange of intelligence on cyber threats."},"oakhaven-migration-aide":{"hook":"“Mr President, your border is under strain. So is ours. Let’s close ranks, without raising our voices.”","news":"London extends a hand to Paris on migration","scene":{"intro":"Oakhaven wrote his speech on a corner of a tablecloth, and insists on reading you half of it.","nodes":{"n1":{"text":"I propose a joint fund, patrols, and a humanist communiqué drafted with the lawyers.","choices":[{"label":"Accept the joint fund"},{"label":"Demand legal routes of entry"},{"label":"Refuse any cooperation"}]},"n2":{"text":"What if we coordinated our reception centres? I say coordinated, not financed.","choices":[{"label":"Share the costs"},{"label":"Keep reception under national control"}]}}},"motif":"Oakhaven proposes joint help in the face of migration tensions."},"oakhaven-defense-moderne":{"hook":"“I am considering a ‘modernised’ defence agreement, Mr President. That is, an old one, but better printed.”","news":"London and Paris revive their defence entente","scene":{"intro":"Oakhaven speaks of shared history with the air of someone already tallying the bill.","nodes":{"n1":{"text":"We would share naval assets, exercises and a meeting room. The meeting room matters most to me.","choices":[{"label":"Accept the naval alliance"},{"label":"Propose a lighter format: joint exercises"}]},"n2":{"text":"For the funding, let’s say 40-60. Your share being, of course, the larger.","choices":[{"label":"Demand 50-50 in exchange for access to finance"},{"label":"Accept the proposed split"},{"label":"Refuse cost sharing"}]}}},"motif":"Oakhaven proposes modernising the Franco-British defence alliance."},"oakhaven-appel-manche":{"hook":"“Mr President, the sea is calm and my advisers are not. A little chat?”","news":"London wants to talk Channel: tea on the line, file in hand","motif":"Oakhaven wants to negotiate an agreement on Channel crossings.","phone":{"intro":"At the other end of the line, you can hear Oakhaven stirring a tea nobody asked for. Today's file: the Channel, Europe's narrowest and most complicated sea.","nodes":{"n3":{"text":"Excellent. We shall discuss all this again on the next call, over another tea. That is how History is built.","labels":{"0":"Agree with dignity","1":"Offer a coffee on the next call, on principle"}}}}},"oakhaven-appel-finance":{"hook":"“The markets are jittery, Mr President. So is the City. We could be jittery together, in good order.”","news":"London asks Paris for banking flexibility","motif":"Oakhaven wants to negotiate reciprocal access for financial services.","phone":{"intro":"Oakhaven calls from a private club where nobody speaks; people communicate by clearing their throats. He takes the opportunity to slip in some demands.","nodes":{"n3":{"text":"The Prime Minister ends the call the way one validates a document: without warmth, but with a certain firmness.","labels":{"0":"Hang up and report back to Paris"}}}}},"zhao-batteries-quotas":{"hook":"“Mr President, a proverb says the battery that waits ends up charged. Let’s talk about yours.”","news":"Batteries: Zhao Lüming and the Élysée discuss deliveries","scene":{"intro":"Zhao lets a long silence pass down the line. Then comes an offer, wrapped in three proverbs.","nodes":{"n1":{"text":"“Our charging stations could cover your motorways. Our trucks too. Only your signature is missing, and your patience.”","choices":[{"label":"Order the stations in bulk, on a tight schedule"},{"label":"Demand assembly in France before any order"},{"label":"Thank him without promising anything"}]},"n2":{"text":"“One doesn’t count the rice before the harvest. When should I hope for your answer?”","choices":[{"label":"Promise an answer before the end of the quarter"},{"label":"Ask for time to consult industrialists"}]}}},"motif":"Zhao offers to expand deliveries of batteries and charging stations."},"zhao-plainte-douanes":{"hook":"“Mr President, your new law has reached our ports. Our containers, meanwhile, remain on the quay.”","news":"Beijing protests a French law, Paris promises “a calm dialogue”","scene":{"intro":"Zhao speaks softly, which is a bad sign. A spokesperson is already preparing three communiqués just in case.","nodes":{"n1":{"text":"“A tree that bends does not break. But your rules mostly bend our trucks. A gesture would be appreciated.”","choices":[{"label":"Promise a review of the standards for Chinese products"},{"label":"Defend the law: it applies to everyone"},{"label":"Propose a working group with no timetable"}]},"n2":{"text":"“A working group is a rowing boat. One still has to know who rows, and where to.”","choices":[{"label":"Appoint a negotiator, with a public roadmap"},{"label":"Talk about the weather with elegance"}]}}},"motif":"Zhao complains that a French law hampers his country’s exports."},"zhao-visite-pandas":{"hook":"“Mr President, my pandas dream of Paris, and I of your cheeses. Would you host us next quarter?”","news":"Zhao Lüming mentions a state visit, the pandas already on the programme","scene":{"intro":"Zhao prepared this call like a tea ceremony. The proposal comes after ten minutes of introduction.","nodes":{"n1":{"text":"“A state visit is a long march. I would gladly bring three hundred people, two pandas and a choir.”","choices":[{"label":"Accept the state visit for next quarter"},{"label":"Politely decline: the diary is a headache"}]},"n2":{"text":"“With us, protocol is an art. Who opens the door first?”","choices":[{"label":"You, of course: the guest first"},{"label":"Together, in a single gesture"}]}}},"motif":"Zhao proposes a state visit to France, pandas included."},"zhao-condoleances-intemperies":{"hook":"“Mr President, the river took what did not belong to it. My people think of yours.”","news":"Zhao Lüming sends France his condolences after the floods","scene":{"intro":"Zhao calls with no agenda, which is rare. His voice is lower than usual, and so is the interpreter’s.","nodes":{"n1":{"text":"“We have dyke engineers and thousands of sandbags. Proverbs, for their part, do not hold back water.”","choices":[{"label":"Accept the team of engineers and their pumps"},{"label":"Thank him, but insist France will manage alone"}]},"n2":{"text":"“When the river calms, one counts the bridges. If you rebuild, my companies would gladly do it.”","choices":[{"label":"Launch an open call for tenders, Chinese companies included"},{"label":"Reserve the reconstruction for French companies"}]}}},"motif":"Zhao offers his condolences after the floods and proposes his help."},"zhao-alliance-recyclage":{"hook":"“Mr President, the summit approaches. Let us walk side by side in front of the press, and closer still behind it.”","news":"Before the summit, Zhao Lüming and the Élysée display “climate convergence”","scene":{"intro":"Ahead of the summit, Zhao no longer talks of markets but of “families of metals”. Behind him, someone coughs, perhaps in code.","nodes":{"n1":{"text":"“I propose a recycling alliance: your factories, our supply chains, a joint fund. As for communication, a little discretion…”","choices":[{"label":"Announce the alliance officially at the summit"},{"label":"Secretly sign a joint off-budget fund","secret":{"leakNews":"LEAK — A Franco-Chinese joint fund on metals recycling, signed off-budget"}},{"label":"Keep your distance until after the summit"}]},"n2":{"text":"“Good. The dragon has the patience of bamboo. What shall we tell the journalists?”","choices":[{"label":"“Transparent cooperation for the climate”"},{"label":"“No comment, but the conversation was excellent”"}]}}},"motif":"Zhao proposes a metals-recycling alliance ahead of the summit."},"zhao-aide-vaccins":{"hook":"“Mr President, my laboratories have too many vaccines and proverbs in reserve. Which do you prefer?”","news":"Beijing offers France batches of vaccines, Paris “studies the offer”","scene":{"intro":"Zhao seems almost in a hurry, which, for him, means he has more than one idea at the back of his mind.","nodes":{"n1":{"text":"“Ten million doses are ready to leave. Sincere help, of course. The thanks can come later.”","choices":[{"label":"Accept the doses, subject to European checks"},{"label":"Accept them with public thanks"},{"label":"Decline: Europe will order for itself"}]},"n2":{"text":"“A gift is an open door. An open door calls for one more step: joint research, perhaps?”","choices":[{"label":"Sign a research cooperation, shared patents"},{"label":"Refer the matter to the European Medicines Agency"}]}}},"motif":"Zhao offers batches of vaccines and medical equipment."},"zhao-appel-terres-rares":{"hook":"“Mr President, my minerals and your patience have finally met. A tea each, on either end of the line?”","news":"Rare earths: Zhao Lüming and the Élysée talk, the tea steeps","motif":"Zhao wants to conclude the rare-earths agreement, teacup in hand.","phone":{"intro":"On the phone, Zhao lets a green tea steep in silence: you can barely hear the porcelain. He finally speaks: “The stability of supply chains is a shared virtue.”"}},"zhao-appel-marches":{"hook":"“Mr President, your consumers want our cars. Your manufacturers, a little less. Let us talk.”","news":"Zhao Lüming praises his electric cars to the Élysée","motif":"Zhao praises his electric vehicles and wants to open the European market.","phone":{"intro":"Zhao boasts over the phone of an electric-vehicle factory that produces more in one day than an entire region. The tone is as cordial as it is strategic."}},"strogov-plainte-sanctions":{"hook":"“Mr President, your sanctions are a work of art: everyone admires them, nobody understands them.”","news":"Moscow denounces the new sanctions, Paris holds its position","scene":{"intro":"The line is bad, but Strogov’s voice comes through perfectly. He has chosen irony as his official language.","nodes":{"n1":{"text":"“History has known forty-two rounds of sanctions. None ended with a thank-you. What exactly are you looking for?”","choices":[{"label":"Explain that the sanction targets officials, not the people"},{"label":"Offer to ease the measure in exchange for concrete gestures"},{"label":"Reply with an even older quotation"}]},"n2":{"text":"“Good. I note your firmness. I also note that it costs your exporters dearly. We shall speak again, in another tone.”","choices":[{"label":"“Whenever you like, but with facts”"},{"label":"Propose an exchange of technical notes"}]}}},"motif":"Strogov protests the new sanction targeting his country."},"strogov-menace-deploiement":{"hook":"“Mr President, your soldiers travel a lot. We have a saying: whoever approaches the border approaches the weather.”","news":"Moscow warns Paris after troop deployment","scene":{"intro":"Strogov never raises his voice. He lowers it, until the microphone itself feels guilty.","nodes":{"n1":{"text":"“I am not threatening. I am observing. My observations have, alas, consequences. Withdraw, or explain yourselves.”","choices":[{"label":"Keep the troops: the deployment is defensive"},{"label":"Propose a deconfliction protocol"},{"label":"Demand a public meeting at the UN"}]},"n2":{"text":"“The UN is a fine building, with fine coffee. Do you really want my diplomats to go there?”","choices":[{"label":"Yes, in transparency"},{"label":"No, prefer direct contact between militaries"}]}}},"motif":"Strogov threatens “appropriate responses” after troops were sent near his borders."},"strogov-ble-engrais":{"hook":"“Mr President, wheat knows no politics. It only knows the calendar. Let us talk sowing.”","news":"Wheat and fertiliser: Strogov and the Élysée discuss sowing, far from the communiqués","scene":{"intro":"Strogov calls from a room where, in the distance, a tractor can be heard. The rural atmosphere is probably staged.","nodes":{"n1":{"text":"“Fertiliser is short for your farmers. Wheat is short for your bakers. History loves these symmetries.”","choices":[{"label":"Negotiate fertiliser deliveries for your farmers"},{"label":"Refuse: no trade during tensions"},{"label":"Go through neutral intermediaries"}]},"n2":{"text":"“A harvest is a promise. Promises, like loaves, are best shared. You will have your share.”","choices":[{"label":"Take the share, publishing the contract"},{"label":"Leave the wheat to countries that lack it, paying for transport"}]}}},"motif":"Strogov wants to talk grain and fertiliser for the sowing season."},"strogov-sommet-photo":{"hook":"“Mr President, a summit without me is a banquet without bread. Let us talk about what will be said before the cameras.”","news":"On the margins of the summit, Strogov demands a one-on-one with Paris","scene":{"intro":"Strogov has a rare talent: turning an invitation into a demand without ever uttering the word “demand”.","nodes":{"n1":{"text":"“One photo, two handshakes, three smiles. My country and yours at the same table: that is what I call history.”","choices":[{"label":"Accept the sideline meeting, in front of the cameras"},{"label":"Propose a multilateral format instead, with your allies"}]},"n2":{"text":"“Rest assured: I will say nothing you cannot repeat. That does, I admit, reduce my vocabulary.”","choices":[{"label":"Agree on a very short joint declaration"},{"label":"Agree to declare nothing"}]}}},"motif":"Strogov demands a meeting on the margins of the summit to appear as an unavoidable power."},"strogov-visite-tapis":{"hook":"“Mr President, you have seen my corridors. Let us now see yours. I would come with few people: two hundred.”","news":"Strogov requests a state visit to Paris, the Élysée “studies the protocol”","scene":{"intro":"Strogov wishes to visit France the way one enters a room where one has always had a reserved armchair.","nodes":{"n1":{"text":"“I ask for neither honours nor orchestra. Only a carpet long enough to be noticed from the Moon.”","choices":[{"label":"Accept the state visit for next quarter"},{"label":"Decline: the calendar is saturated with historic moments"}]},"n2":{"text":"“Whatever your choice, I appreciate your frankness. I shall keep it, like everything else, in very deep archives.”","choices":[{"label":"Thank him and propose a lunch without protocol"},{"label":"Reply: “History is patient”"}]}}},"motif":"Strogov requests a state visit to have his role as an unavoidable power recognised."},"strogov-renseignement-cyber":{"hook":"“Mr President, there are pirates in your hospitals and alibis in my drawers. Shall we swap notes?”","news":"Cyberattack: Strogov offers “technical cooperation”, Paris stays cautious","scene":{"intro":"Strogov speaks of hacking with a gardener’s serenity. You prefer not to ask who planted what.","nodes":{"n1":{"text":"“Someone is making trouble for you, and that someone does not always sleep in Russia. Here are some leads. They cost almost nothing.”","choices":[{"label":"Receive the leads in secret, without attributing them","secret":{"leakNews":"REVEALED — The Élysée reportedly received cyber “leads” from Moscow in secret"}},{"label":"Ask for the evidence officially, via European agencies"},{"label":"Thank him and file it away"}]},"n2":{"text":"“One last thing. If the pirates turn out to be friends, not a word. Friends are rare, pirates too, but less discreet.”","choices":[{"label":"Agree on a direct line between technicians"},{"label":"Demand public attribution of the culprits"}]}}},"motif":"Strogov offers to exchange information about the cyberattack hitting France."},"strogov-appel-canal":{"hook":"“Mr President, everyone is indignant in public. I propose we talk in private.”","news":"War: Moscow and Paris reportedly “exchanged a few words”","motif":"Strogov proposes a discreet channel to calm things down during the conflict.","phone":{"intro":"You are kept holding for forty minutes, between two switchboard operators and some martial hold music. Strogov finally picks up, barely apologises, then suggests you forget everything you said in public."}},"strogov-appel-energie":{"hook":"“Mr President, your radiators are cold, my gas pipelines are lukewarm. Let us talk.”","news":"Energy: Strogov offers Paris to “talk geography”","motif":"Strogov offers to talk gas and spare parts in the middle of the energy crisis.","phone":{"intro":"Strogov calls from a windowless room, “for concentration”. You can hear him unfolding a map of the continent, with very persuasive arrows.","nodes":{"n3":{"text":"Strogov ends the call with a measured phrase and thanks you for your “attentiveness”. You check, out of caution, that the line is really dead.","labels":{"0":"Hang up without another word","1":"Promise him a symbolic gift"}}}}},"brancalessi-felicitations-sport":{"hook":"“My dear friend, what a victory! I weep, I sing, I pretend not to be jealous! Congratulations to France!”","news":"Rome congratulates Paris on its sporting success, “with the grandeur of an opponent”","scene":{"intro":"Brancalessi calls from a stadium, or an opera house, or a stadium that looks like an opera house. Trumpets can be heard.","nodes":{"n1":{"text":"“Bravo! Your athletes are magnificent! Ours, shall we say, are… busy preparing for next time.”","choices":[{"label":"Thank him and propose a friendly match between the two countries"},{"label":"Gently remind him of the latest standings"},{"label":"Stay sober and institutional"}]},"n2":{"text":"“To celebrate, a six-hour lunch! Or seven, if we talk about sport. What do you say?”","choices":[{"label":"Accept, for the photo"},{"label":"Propose a joint ceremony for amateur clubs"}]}}},"motif":"Brancalessi congratulates France on its sporting success, with barely veiled jealousy."},"brancalessi-plainte-frontiere":{"hook":"“My friend, the Mediterranean knows no borders, but Paris, apparently, knows its own very well!”","news":"Rome reproaches Paris for its closed border, “a drama in three acts”","scene":{"intro":"Brancalessi sighs so loudly the handset trembles. The sigh lasts longer than yesterday’s call.","nodes":{"n1":{"text":"“I tell you with pain: your gendarmes send back to us what Brussels already sends us. It is a tragic opera!”","choices":[{"label":"Promise reinforcements for reception and screening at the border"},{"label":"Defend your checks: security first"},{"label":"Propose a joint Franco-Italian patrol"}]},"n2":{"text":"“You speak gold, my friend. But gold feeds nobody. What is needed is a gesture everyone can see!”","choices":[{"label":"Announce a European conference on burden-sharing"},{"label":"Promise a fund for border municipalities"}]}}},"motif":"Brancalessi reproaches France for closing its border while Italy takes in more."},"brancalessi-visite-opera":{"hook":"“My dear president, I dreamed of Paris while singing Verdi. Grant me a state visit, and I shall sing for you!”","news":"Brancalessi announces his wish for a state visit, “with an evening at the opera”","scene":{"intro":"Brancalessi has already chosen the tie for the visit, and the one for the return visit. He is only waiting for your green light.","nodes":{"n1":{"text":"“We shall bring wine, songs and a naval contract as a gift. You need only say yes!”","choices":[{"label":"Accept the state visit for next quarter"},{"label":"Decline with elegance: the diary is a headache"}]},"n2":{"text":"“Whatever your choice, the Italian heart stays open, and so do the suitcases. What would you like on the menu?”","choices":[{"label":"A grand table of French produce"},{"label":"A menu from here and there, informal"}]}}},"motif":"Brancalessi proposes a state visit to France, with a choir and an evening at the opera."},"brancalessi-aide-incendies":{"hook":"“My dear friend, the forest burns, and my heart with it! My water bombers are already in the air!”","news":"Wildfires: Rome sends its water bombers, “out of friendship more than protocol”","scene":{"intro":"Brancalessi shouts the emergency into the handset, then whispers that his planes are already airborne. He loves the element of surprise.","nodes":{"n1":{"text":"“Four water bombers, twenty firefighters, and a chief who sings to calm the troops! Say yes, I beg you!”","choices":[{"label":"Accept with gratitude and a joint communiqué"},{"label":"Accept the help, without publicising it"},{"label":"Refuse: France has its own means"}]},"n2":{"text":"“Once the flames are out, let us talk reforestation. A joint project, twenty thousand trees, a single orchestra!”","choices":[{"label":"Launch a Franco-Italian reforestation programme"},{"label":"Refer the idea to the European agency"}]}}},"motif":"Brancalessi sends water bombers and firefighters during the wildfire crisis."},"brancalessi-sommet-mediterranee":{"hook":"“My dear president, the summit approaches! Let us make Italy, France and the Mediterranean heard with one voice!”","news":"Before the summit, Rome and Paris want to “speak with one voice”","scene":{"intro":"Brancalessi has planned three speeches: one for the press, one for you, and one for himself, in front of the mirror.","nodes":{"n1":{"text":"“A joint declaration, two flags, a single dream: that Europe listens to us, for once, with open ears!”","choices":[{"label":"Sign the joint declaration on the Mediterranean"},{"label":"Impose your amendments before signing"}]},"n2":{"text":"“Perfect! During the summit, we shall sit side by side and laugh at the same jokes, in two languages!”","choices":[{"label":"Laugh on cue, for the photo"},{"label":"Reply with a well-aimed joke"}]}}},"motif":"Brancalessi proposes a joint Franco-Italian position before the summit."},"brancalessi-cuisine-contrats":{"hook":"“My friend, let us talk contracts! My country produces, yours buys, and nobody gets angry, except the chefs.”","news":"Rome and Paris discuss contracts, “in good spirits”","scene":{"intro":"Brancalessi has had a file of contracts and a cheese sent by courier. You receive both with equal apprehension.","nodes":{"n1":{"text":"“My construction, energy and fashion companies want to work with yours. It will be beautiful as an aria!”","choices":[{"label":"Open a joint counter for SMEs of both countries"},{"label":"Reserve public contracts for French companies"},{"label":"Sign a few targeted contracts, sector by sector"}]},"n2":{"text":"“One detail remains: the cheese. I sent forty kilos. You cannot say no to forty kilos!”","choices":[{"label":"Give them to school canteens"},{"label":"Keep them for a tasting at the Élysée"}]}}},"motif":"Brancalessi proposes contracts for his companies, with plenty of culinary metaphors."},"brancalessi-appel-migrations":{"hook":"“My friend, the Mediterranean did not empty while we talked. Let us meet again, at last!”","news":"Migration: Rome and Paris meet again, “for a shorter drama”","motif":"Brancalessi wants to conclude a migrant-sharing mechanism and naval contracts.","phone":{"intro":"Brancalessi calls from a seaside terrace: you hear waves and cutlery. From his voice you can tell he is waving his arms; he evokes Rome, the Alps and European solidarity with exquisite pain.","nodes":{"n3":{"text":"Bellissimo! We shall celebrate on your next trip, with a six-hour lunch. You have nothing planned that day, have you?","labels":{"0":"Promise to come for lunch one day","1":"Plead another appointment"}}}}},"brancalessi-appel-budget":{"hook":"“My dear president, the markets tremble, the Excel sheets threaten us! Let us make common cause!”","news":"Budget rules: Rome and Paris want “more flexibility”","motif":"Brancalessi proposes a common front against European budget rules.","phone":{"intro":"Brancalessi calls you privately before the European summit, lowering his voice. “We must talk about the Pact, you and I. Two old friends who hate Excel spreadsheets.”","nodes":{"n3":{"text":"Down the line, you hear Brancalessi downing a cup of espresso in one go. The deal is sealed, or at least tasted, with remarkable intensity.","labels":{"0":"Toast from afar with a “Salute!”"}}}}},"rajvardhan-appel-armement":{"hook":"Mr President, my generals have drawn up a shopping list. It is long, but very courteous.","news":"Rajvardhan received to discuss weapons and technology transfers","motif":"Rajvardhan wants to modernise his army with trusted partners.","phone":{"intro":"On the phone, Rajvardhan's voice echoes as if beneath colonnades. He immediately mentions the size of his population, apologetically, with a gleam in his voice."}},"rajvardhan-appel-numerique":{"hook":"Mr President, my engineers have read the newspapers. They are thinking of you and your servers.","news":"Tech visas and cybersecurity on the menu of a meeting with Rajvardhan","motif":"Rajvardhan offers tech visas and cybersecurity cooperation.","phone":{"intro":"Rajvardhan calls from a start-up incubator where nobody sleeps: you hear keyboards and tired but highly motivated people.","nodes":{"n3":{"text":"An intern takes the receiver and quietly asks whether you might be short of a developer.","labels":{"0":"Take note of his CV with interest","1":"Decline and end the call"}}}}},"rajvardhan-visite-etat":{"hook":"Mr President, my diary is empty for you. Well, it’s full, but I scraped half of it clear.","news":"Rajvardhan expected for a state visit, record delegation announced","scene":{"intro":"On the phone you hear stamps thumping: the Prime Minister’s office is making your conversation official before it has even ended.","nodes":{"n1":{"text":"Come, or rather let me come! A state visit would be a fine symbol, and a fine occasion to sign things.","choices":[{"label":"Accept his state visit next quarter"},{"label":"Politely decline: diary too full"}]},"n2":{"text":"In any case, my office will send you a forty-page file. With an index, out of consideration for you.","choices":[{"label":"Promise to read it all"},{"label":"Ask for a short version"}]}}},"motif":"Rajvardhan wishes to make a state visit to France."},"rajvardhan-plainte-sanctions":{"hook":"Mr President, I learned of your sanctions from the press. I would have preferred a little word. Even a Post-it.","news":"Rajvardhan publicly worries about sanctions decided by Paris","scene":{"intro":"The Prime Minister calls on the secure line. His voice still smiles, but this time the smile is slightly more strained than usual.","nodes":{"n1":{"text":"We are friends with everyone, including those you sanction. This creates situations of great delicacy.","choices":[{"label":"Assure him his partners are out of the crosshairs"},{"label":"Recall that firmness is a principle"},{"label":"Propose a trade monitoring committee"}]},"n2":{"text":"Perfect, a committee. And a sub-committee to monitor the committee. I love recursive transparency.","choices":[{"label":"Accept the sub-committee"},{"label":"Refuse to multiply committees"}]}}},"motif":"Rajvardhan complains about sanctions and demands visibility for his companies."},"rajvardhan-felicitations-succes":{"hook":"Mr President, bravo! My astrologer had predicted your success. He had also predicted my cousin’s, so…","news":"Rajvardhan hails French success: “A great moment”","scene":{"intro":"The Prime Minister calls with the sound of confetti in the background, which his office swears it did not order.","nodes":{"n1":{"text":"A success like that is to be shared! My country has engineers, laboratories and a nice invoice to present to you. Sorry, a proposal.","choices":[{"label":"Propose a research partnership"},{"label":"Thank him warmly without promising anything"}]},"n2":{"text":"We shall organise a joint conference: twenty-five speakers, all brief. Well, brief for a symposium.","choices":[{"label":"Send a minister in person"},{"label":"Take part by video, it’s more sober"}]}}},"motif":"Rajvardhan congratulates France on its recent success."},"rajvardhan-condoleances-epreuve":{"hook":"Mr President, my thoughts are with you. Mine, and those of my office, which stayed up all night over the wording.","news":"Rajvardhan sends his condolences and offers support to France","scene":{"intro":"The Prime Minister’s voice is lower than usual. Not a demographic statistic in sight.","nodes":{"n1":{"text":"We know hardship. I can send you rescue teams and hot tea. Both have proven their worth.","choices":[{"label":"Accept the rescue teams"},{"label":"Thank him, but insist France will manage"}]},"n2":{"text":"The silence that follows is sincere, which is rare in diplomacy. Even the interpreters hold their breath.","choices":[{"label":"Mention the friendship between peoples"},{"label":"Hang up soberly"}]}}},"motif":"Rajvardhan offers his condolences after the tragedy and proposes his help."},"rajvardhan-sommet-equidistance":{"hook":"Mr President, a summit is coming! I shall sit at equal distance from everyone, measured by laser.","news":"Rajvardhan and Paris coordinate their positions before the summit","scene":{"intro":"The Prime Minister calls between two meetings. You hear him choose a tie live, then change it.","nodes":{"n1":{"text":"I have an idea: an enlarged seat for those who contribute a lot. I won’t say which. I simply smile very hard.","choices":[{"label":"Support an enlargement of seats"},{"label":"Propose a joint declaration on multilateralism"},{"label":"Keep your cards for the summit"}]},"n2":{"text":"For the family photo, where do I stand? I care about the symmetry of the shoulders.","choices":[{"label":"In the centre, side by side"},{"label":"At the back, to offend nobody"}]}}},"motif":"Rajvardhan wants to coordinate his position with yours before the summit."},"rajvardhan-mousson-solaire":{"hook":"Mr President, the monsoon is coming and my engineers dream of solar panels. A lot of panels.","news":"A Franco-Indian solar programme mentioned over the phone","scene":{"intro":"The Prime Minister calls from a balcony, with an oncoming rain and a chorus of fans in the background.","nodes":{"n1":{"text":"Twenty thousand roofs await their panels. One gesture from you, and I make you the hero of twenty thousand roofs.","choices":[{"label":"Fund a first batch of solar plants"},{"label":"Propose a subsidised loan rather than a grant"},{"label":"Refuse: the budget is tight"}]},"n2":{"text":"To thank you, I shall send you a basket of mangoes. It will be weighed, counted and eaten with joy.","choices":[{"label":"Accept the basket with a big smile"},{"label":"Have it distributed to a school canteen"}]}}},"motif":"Rajvardhan asks for a boost for a solar programme before the monsoon."},"quintanilha-appel-soja":{"hook":"Mr President! Soy, timber, coffee, all this is better negotiated by phone. Especially the coffee.","news":"Quintanilha and Paris discuss a soy agreement","motif":"Quintanilha wants to negotiate a farm deal without being accused of deforestation.","phone":{"intro":"Quintanilha calls from an auditorium under the palm trees and talks without notes for twenty minutes. You understand most of it, and the essential: he wants a trade deal.","nodes":{"n3":{"text":"Ótimo! We shall celebrate when you visit. Do you dance? No? No matter, we will teach you.","labels":{"0":"Promise to learn the samba"}}}}},"quintanilha-appel-ressources":{"hook":"Mr President, everyone calls me for my lithium. You, at least, call to talk about me.","news":"Lithium and factories: Quintanilha pleads for added value","motif":"Quintanilha wants factories at home rather than ore trucks.","phone":{"intro":"Quintanilha calls from a small plane flying over the forest: the engine half drowns out his voice. The mood is grandiose, a little solemn, with a strong hint of photo shoot.","nodes":{"n3":{"text":"The plane takes a rather sharp turn; you hear Quintanilha laugh, then the line cuts out for a moment. He laughs, you much less so.","labels":{"1":"Ask him to call back from the ground"}}}}},"quintanilha-visite-etat":{"hook":"Mr President, I’m coming to see you! I bring a delegation, a brass band and my personal drum.","news":"Quintanilha says he wants a state visit, brass band included","scene":{"intro":"Quintanilha calls you from a stage. You can hear applause, which is odd for a simple phone call.","nodes":{"n1":{"text":"I shall come to talk about the forest, agriculture, the future. And taste your cheeses, with diplomatic moderation.","choices":[{"label":"Accept his state visit next quarter"},{"label":"Politely decline, with a vague postponement"}]},"n2":{"text":"Ótimo! For the ceremony, I plan ten minutes of speech. Let’s say twenty. Let’s say I’ll improvise.","choices":[{"label":"Allow a generous slot"},{"label":"Slip a stopwatch into the protocol"}]}}},"motif":"Quintanilha proposes a state visit to France."},"quintanilha-plainte-loi":{"hook":"Mr President, I have read your new law. It talks about my country without naming me. I like to be named.","news":"Quintanilha criticises a French law deemed unfavourable to his producers","scene":{"intro":"Quintanilha's voice booms as from a podium, though the echo betrays an empty corridor.","nodes":{"n1":{"text":"I’m not asking for a special favour, only a little respect. And a special favour, if possible.","choices":[{"label":"Propose an adaptation clause for his producers"},{"label":"Defend the law without flinching"},{"label":"Promise a review clause in a year"}]},"n2":{"text":"A clause, then. Let my producers read it without translator or lawyer. Especially without a lawyer.","choices":[{"label":"Promise a clear, short text"},{"label":"Refer to the legislative calendar"}]}}},"motif":"Quintanilha is irritated by a law that penalises his exports."},"quintanilha-aide-incendies":{"hook":"Mr President, when a forest burns somewhere, the whole world coughs. You cough too, don’t you?","news":"Wildfires: Quintanilha offers France climate cooperation","scene":{"intro":"Quintanilha speaks from a helicopter. He shouts to cover the noise, making for a very energetic conversation.","nodes":{"n1":{"text":"My forest firefighters are ready to share their experience. My planes are ready too, but they are waiting for an extension.","choices":[{"label":"Fund an exchange of experts and equipment"},{"label":"Accept the exchange, without the equipment"},{"label":"Decline: France has its own fires"}]},"n2":{"text":"We shall publish a joint communiqué. A communiqué is like a song: it needs a chorus.","choices":[{"label":"Propose a chorus on forest and climate"},{"label":"Stick to a technical text"}]}}},"motif":"Quintanilha proposes wildfire cooperation and asks for funding."},"quintanilha-felicitations-victoire":{"hook":"Mr President, congratulations! Back home, we celebrate for three days. Then we rest for two more.","news":"Quintanilha congratulates France: “This deserves three days of celebration”","scene":{"intro":"You hear music and laughter before Quintanilha picks up the handset, slightly out of breath.","nodes":{"n1":{"text":"You should come and celebrate here. I promise you an unforgettable party and a minister who will dance badly to reassure you.","choices":[{"label":"Promise a visit soon to celebrate"},{"label":"Thank him, but stay focused on work"}]},"n2":{"text":"At least a toast from afar! Cheers, Mr President. And to ours, of course.","choices":[{"label":"Toast warmly from a distance"},{"label":"Raise a toast to cooperation between our peoples"}]}}},"motif":"Quintanilha congratulates France on its success."},"quintanilha-alliance-foret-climat":{"hook":"Mr President, before the climate conference, an idea: what if we made common cause? You, me, and many trees.","news":"Paris and Quintanilha sketch a common front on climate","scene":{"intro":"Quintanilha whispers down the phone, which is suspicious in an orator of his calibre.","nodes":{"n1":{"text":"Together we would ask for a global forest fund. You bring the credibility, I bring the trees.","choices":[{"label":"Commit to a global forest fund"},{"label":"Propose a joint declaration without figures"},{"label":"Stay cautious: wait for the other donors"}]},"n2":{"text":"Perfect. For the ceremony, I shall read a short speech. Forty minutes, maximum, so as not to tire the forest.","choices":[{"label":"Plan a joint press conference"},{"label":"Publish a simple communiqué"}]}}},"motif":"Quintanilha proposes a common front on forests and climate."},"quintanilha-sommet-voix":{"hook":"Mr President, a summit! I intend to make my country’s voice heard there. And my own, which carries.","news":"Quintanilha wants to weigh in at the summit and asks Paris for backing","scene":{"intro":"Quintanilha calls you from a plane. Turbulence accompanies the start of the conversation.","nodes":{"n1":{"text":"I would like my country to be better represented in the major bodies. History owes us an armchair, Mr President.","choices":[{"label":"Publicly support his country for an enlarged seat"},{"label":"Promise discreet support behind the scenes"},{"label":"Remind him that other countries will need convincing"}]},"n2":{"text":"I shall go round the delegations. If someone asks where my seat is, I’ll say: where people agree.","choices":[{"label":"Offer to accompany him in his talks"},{"label":"Let him go it alone"}]}}},"motif":"Quintanilha wants to weigh in more at the next summit and seeks your backing."},"benkhadra-appel-gaz":{"hook":"Mr President, the cold season approaches. You need gas, we need respect. Let us talk without delay.","news":"Gas, visas and memories: a delicate talk with Benkhadra","motif":"Benkhadra wants to talk gas, visas and memories all at once.","phone":{"intro":"On the secure line, Benkhadra picks up on the second ring, then lets an eloquent silence hang. He thanks you for calling “despite all that separates us, and all that unites us”.","nodes":{"n3":{"text":"Good. We are moving forward, slowly but surely. Call me back once you have reread the file; the line is on the house.","labels":{"0":"Gratefully agree to continue"}}}}},"benkhadra-appel-economie":{"hook":"Mr President, I do not wish to depend on a single customer. Can we talk about a more varied menu?","news":"Benkhadra pleads for diversification of the Algerian economy","motif":"Benkhadra wants to diversify his economy with investment and training.","phone":{"intro":"On the secure line, Benkhadra's voice is more modest but very orderly: he discusses the country's economy, its diversification ambitions, and his distrust of promises that are too good.","nodes":{"n3":{"text":"The president concludes without a word too many. A long silence follows down the line, as if he were reading archives.","labels":{"0":"Hang up in silence","1":"Promise to call back"}}}}},"benkhadra-visite-etat":{"hook":"Mr President, I believe the time has come for us to receive each other. At my place, this time.","news":"Benkhadra considers a state visit: an awaited gesture","scene":{"intro":"Benkhadra speaks calmly, as if weighing every syllable on a goldsmith’s scale.","nodes":{"n1":{"text":"A state visit is an act of respect. I shall come with dignity, punctuality and a programme I shall re-read myself.","choices":[{"label":"Accept his state visit next quarter"},{"label":"Politely decline, with a vague postponement"}]},"n2":{"text":"I insist on one point: no staging. Actions. And mint tea, all the same.","choices":[{"label":"Promise a sober, concrete programme"},{"label":"Propose a grand state dinner"}]}}},"motif":"Benkhadra is considering a state visit to France."},"benkhadra-plainte-fuite":{"hook":"Mr President, I have read a record that should never have been read. I find it instructive, but indignant.","news":"Benkhadra protests after a confidential report leaks","scene":{"intro":"Benkhadra breathes slowly. At the other end of the line, the interpreter falls respectfully silent.","nodes":{"n1":{"text":"Trust is built in secret and lost in public. What do you have to say about this paper that is circulating?","choices":[{"label":"Offer a sober and sincere apology"},{"label":"Contest the document’s authenticity"},{"label":"Point out the leak may have come from both sides"}]},"n2":{"text":"I am not asking for theatre. I am asking that we do what we said. That is called consistency.","choices":[{"label":"Commit to better protecting exchanges"},{"label":"Offer to publish everything, as a full settlement"}]}}},"motif":"Benkhadra protests after a confidential report on gas and visas leaks."},"benkhadra-menace-gel":{"hook":"Mr President, my country does not raise its voice. It sometimes withdraws its chair, which makes a lot of noise.","news":"Benkhadra threatens to suspend cooperation with Paris","scene":{"intro":"The silence before Benkhadra speaks lasts long enough for you to check that the line hasn’t been cut.","nodes":{"n1":{"text":"We shall suspend certain cooperation if these measures continue. I say so without anger, but without ambiguity.","choices":[{"label":"Suspend the measures and reopen dialogue"},{"label":"Maintain firmness while offering a framework for discussion"},{"label":"Propose a discreet mediator"}]},"n2":{"text":"A mediator, then. Let him be discreet, patient and of an age that inspires respect.","choices":[{"label":"Appoint a respected former ambassador"},{"label":"Entrust the mission to a cabinet adviser"}]}}},"motif":"Benkhadra threatens to suspend cooperation if the pressure continues."},"benkhadra-condoleances":{"hook":"Mr President, at this hour there is neither file nor disagreement. There is grief, and it is shared.","news":"Benkhadra sends his condolences to the French people","scene":{"intro":"Benkhadra’s voice is grave and slow. He lets the silences do their work on purpose.","nodes":{"n1":{"text":"Peoples know each other in hardship. I say it simply: if you need anything at all, you need only ask.","choices":[{"label":"Thank him and mention the friendship between peoples"},{"label":"Accept logistical and medical aid"},{"label":"Thank him briefly and hang up"}]},"n2":{"text":"At the other end, a long respectful silence. Even the crackle of the line seems to have lowered its tone.","choices":[{"label":"Propose meeting soon for a talk"},{"label":"Say thank you and end the call"}]}}},"motif":"Benkhadra offers his condolences to the French people."},"benkhadra-renseignement-sahel":{"hook":"Mr President, in the Sahel, everyone sees a piece of the map. Let us put our pieces together, discreetly.","news":"Sahel security: Paris and Algiers talk","scene":{"intro":"Benkhadra chooses his words the way one chooses allies: few, but carefully.","nodes":{"n1":{"text":"I have information on certain trafficking. You have some on certain networks. The exchange must be honest, and above all discreet.","choices":[{"label":"Share intelligence, in full discretion","secret":{"leakNews":"LEAK — An intelligence exchange between Paris and Algiers on the Sahel revealed by the press"}},{"label":"Share only non-sensitive information"},{"label":"Keep your sources to yourself"}]},"n2":{"text":"Good. We shall see with use. With us, they say friendship is measured by the quality of silence.","choices":[{"label":"Appoint a single point of contact for exchanges"},{"label":"Keep a direct line between offices"}]}}},"motif":"Benkhadra proposes an intelligence exchange on armed networks in the Sahel."},"benkhadra-felicitations":{"hook":"Mr President, recognition is paid in deeds, but congratulations are free. So I offer them.","news":"Benkhadra congratulates France: “A result that honours the work”","scene":{"intro":"Benkhadra phones with no apparent protocol, which, for him, is almost a declaration of friendship.","nodes":{"n1":{"text":"I am sincere: a country that succeeds is a neighbour one looks in the eye. I hope it inspires us.","choices":[{"label":"Thank him and propose scientific cooperation"},{"label":"Simply thank him"}]},"n2":{"text":"One last thing: your youth and ours resemble each other. They deserve exchanges, not queues.","choices":[{"label":"Announce a university exchange programme"},{"label":"Mention the subject without promising anything"}]}}},"motif":"Benkhadra congratulates France on its recent success."},"saadallah-ville-futuriste":{"hook":"“Mr President, my city will be one hundred and sixty kilometres long and have zero bends. Your concrete companies would be honoured to take part.”","news":"City of the future in the desert: French companies in the running","scene":{"intro":"The emir calls you from an office where every wall is a screen. On one of them, a virtual crane is already building your embassy.","nodes":{"n1":{"text":"I am looking for partners for the tunnels, the towers and the trains. Who does better than you? Apart from me, of course.","choices":[{"label":"Propose a consortium of companies with clear tenders"},{"label":"Demand payment guarantees before any commitment"},{"label":"Promise everything, the details will come later"}]},"n2":{"text":"Perfect. One detail: the city will run with zero emissions. Except air conditioning, which is a cultural exception.","choices":[{"label":"Offer your solar air-conditioning technology"},{"label":"Stick to the contracts, without talking ecology"}]}}},"motif":"Saadallah wants to involve your companies in his city of the future."},"saadallah-plainte-sanction":{"hook":"“Mr President, I am told you have signed something against my country. I hope it is a printer error.”","news":"Sanctions: Emir Saadallah denounces “a very costly misunderstanding”","scene":{"intro":"The tone is charming, the smile audible. Every sentence is followed by a silence worth a cancelled contract.","nodes":{"n1":{"text":"My sovereign funds are very sensitive. They cry easily, especially in dollars.","choices":[{"label":"Defend the decision and recall the principles"},{"label":"Assure him the measure is temporary and targeted"},{"label":"Propose a discreet channel to defuse things"}]},"n2":{"text":"I am willing to forget the incident. People my age forget quickly, especially billions.","choices":[{"label":"Get a promise that his funds stay invested with you"},{"label":"Refuse any quid pro quo, on principle"}]}}},"motif":"Saadallah protests the sanctions targeting his country."},"saadallah-visite":{"hook":"“Mr President, my delegation numbers two hundred people, three falcons and a pastry chef. When may I come?”","news":"Emir Saadallah expected on a state visit: falcons and pastry chef included","scene":{"intro":"The emir seems to have already booked the date. An adviser murmurs the name of an entire hotel in the background.","nodes":{"n1":{"text":"I would come with gifts, obviously. Do you prefer horses or shares?","choices":[{"label":"Gladly accept the state visit"},{"label":"Politely decline, the diary is saturated"}]},"n2":{"text":"Understood. Just tell me how I should tell the press: friendship or diary?","choices":[{"label":"Speak of a friendship carefully prepared"},{"label":"Speak of the diary, with no further comment"}]}}},"motif":"Saadallah wishes to make a state visit."},"saadallah-felicitations":{"hook":"“Mr President, my congratulations! I had already had the communiqué prepared, only your victory was missing.”","news":"Emir Saadallah congratulates France: “A success you can read in the figures”","scene":{"intro":"The call arrives before the agencies have even finished publishing the news. Emirs have a trader’s reflexes.","nodes":{"n1":{"text":"When someone succeeds, I like to invest alongside them. It’s my way of saying bravo in several zeros.","choices":[{"label":"Thank him and suggest an investment in your start-ups"},{"label":"Simply thank him, promising nothing"}]},"n2":{"text":"Then I dedicate a tower to you. It will bear your name or, failing that, my cousin’s.","choices":[{"label":"Accept the tower, provided it is eco-friendly"},{"label":"Decline the honour with humour"}]}}},"motif":"Saadallah congratulates you on your recent successes."},"saadallah-petrole-hiver":{"hook":"“Mr President, I hear your radiators are coughing. I have barrels that ask only to warm you.”","news":"Energy: Emir Saadallah offers emergency deliveries to France","scene":{"intro":"In the handset, you hear tea being slowly stirred. The emir knows time is on his side.","nodes":{"n1":{"text":"A friend’s price, of course. Friendship is measured in dollars per barrel, as you know.","choices":[{"label":"Accept an emergency contract at a negotiated price"},{"label":"Tie the deliveries to solar investments"},{"label":"Decline, so as not to depend on him"}]},"n2":{"text":"A small clause: you will not comment on my domestic policy. Nothing serious, it fits on one page.","choices":[{"label":"Accept the discretion clause"},{"label":"Refuse the clause and keep your freedom of speech"}]}}},"motif":"Saadallah offers oil and gas deliveries to get through the winter."},"saadallah-sommet-hydrogene":{"hook":"“Mr President, at the coming summit, let us align our positions. I draft, you sign: a nice time saver.”","news":"Before the summit: Paris and Emir Saadallah tune their violins","scene":{"intro":"An adviser sends you a speech already delivered as an attachment. It bears your signature, in facsimile.","nodes":{"n1":{"text":"My country will be ambitious on hydrogen. Very ambitious, as long as it doesn’t touch oil.","choices":[{"label":"Propose a joint declaration on hydrogen"},{"label":"Demand quantified commitments on oil"}]},"n2":{"text":"I am adding a flattering paragraph about you. Do you like flattering paragraphs?","choices":[{"label":"Accept the paragraph, after proofreading"},{"label":"Refuse any compliment and stay sober"}]}}},"motif":"Saadallah wants to coordinate your positions before the summit."},"saadallah-appel-armement":{"hook":"“Mr President, my frigates are impatient, my planes too. I am calling to find out whether your pen is as well.”","news":"Arms contract: Emir Saadallah presses Paris to sign","motif":"Saadallah wants to conclude a big arms contract.","phone":{"intro":"The emir calls from an air-conditioned tent as big as a hangar: a projector hums in the background. He is projecting a model of a city fifty kilometres long. He asks your opinion; in truth he awaits your signature."}},"saadallah-appel-energie":{"hook":"“Mr President, I have re-read my diversification plan. One thing is missing: you, on the first page.”","news":"Diversification: Emir Saadallah offers Paris a solar partnership","motif":"Saadallah wants a partnership on solar and hydrogen.","phone":{"intro":"During the call, an adviser forwards a gilded copy of the diversification plan. The emir has highlighted passages for your attention, but not the ones that concern you.","nodes":{"n3":{"text":"The emir's adviser announces a gift of indecent value is on its way. Protocol demands accepting it, morality demands thinking it over."}}}},"watarase-puces-livraison":{"hook":"“Mr President, our factories have studied the question with the utmost seriousness. The chips will be delivered. Some day soon.”","news":"Semiconductors: Tokyo promises deliveries “as soon as possible”","scene":{"intro":"A long silence precedes Watarase’s voice. He is probably bowing to the handset.","nodes":{"n1":{"text":"We have a slight scheduling issue. I mention it with the greatest humility.","choices":[{"label":"Agree to postpone your industrial orders"},{"label":"Ask for delivery priority for your factories"},{"label":"Offer to fund a joint factory"}]},"n2":{"text":"We are most grateful. Your answer is noted in a notebook, with a pretty brush.","choices":[{"label":"Thank him and propose a business lunch"},{"label":"Ask for a written commitment"}]}}},"motif":"Watarase gives an update on semiconductor deliveries."},"watarase-plainte-commerce":{"hook":"“Mr President, I take the liberty of pointing out, without the slightest intention to inconvenience, that this inconvenienced us a little.”","news":"Tokyo is “astonished with the greatest respect” at Paris’s trade decisions","scene":{"intro":"No voice is raised. However, three apology formulas have already been deployed, just in case.","nodes":{"n1":{"text":"We have studied your trade policy with the utmost seriousness. We have questions, over twelve pages.","choices":[{"label":"Apologise and promise to adjust the text"},{"label":"Defend the decision firmly"},{"label":"Propose a discreet working group"}]},"n2":{"text":"We are very fond of working groups. There are already forty, one more will make no noise.","choices":[{"label":"Accept a regular trade dialogue"},{"label":"Declare the matter closed"}]}}},"motif":"Watarase, very politely, expresses his displeasure."},"watarase-visite-cerisiers":{"hook":"“Mr President, the cherry trees of Tokyo have bloomed in your honour. Allow me to come and see whether yours have done the same.”","news":"Watarase expected in Paris: a state visit under the cherry trees","scene":{"intro":"The Prime Minister apologises three times for having proposed. He has already planned the colour of the tie.","nodes":{"n1":{"text":"I would come in all discretion. With forty people and a three-hour ceremonial, but quietly.","choices":[{"label":"Accept the state visit"},{"label":"Propose postponing to next year"}]},"n2":{"text":"As for gifts, I am thinking. A bonsai is elegant, but I fear it is politically loaded.","choices":[{"label":"Suggest an exchange of books and recipes"},{"label":"Offer more symbolic but more expensive gifts"}]}}},"motif":"Watarase proposes a state visit in spring."},"watarase-condoleances":{"hook":"“Mr President, we learned the news with deep sadness. The silence I offer you is sincere.”","news":"Prime Minister Watarase sends his condolences to a France in mourning","scene":{"intro":"Watarase’s silence is usually an art. Today it is simply sadness.","nodes":{"n1":{"text":"I think of the families. If you allow, I shall send rescue teams and hot tea.","choices":[{"label":"Accept the help and thank him publicly"},{"label":"Accept the help, but in private"},{"label":"Thank him without accepting: France manages alone"}]},"n2":{"text":"With us, we are silent together. Would you like us to keep a minute’s silence over the phone?","choices":[{"label":"Share the minute’s silence"},{"label":"Thank him and go back to crisis management"}]}}},"motif":"Watarase sends you his condolences after the tragedy."},"watarase-cooperation-maritime":{"hook":"“Mr President, in the face of tensions, we have considered standing side by side. Discreetly, in line.”","news":"Tokyo and Paris consider maritime security cooperation","scene":{"intro":"The Prime Minister unfolds a nautical chart annotated in pencil, with apologies in the margins.","nodes":{"n1":{"text":"A defence cooperation, with joint exercises. I propose the name “Spring Breeze”, deliberately unthreatening.","choices":[{"label":"Accept joint naval exercises"},{"label":"Limit it to a strategic dialogue"}]},"n2":{"text":"We also wish to share some intelligence. With the greatest delicacy.","choices":[{"label":"Exchange through an official channel"},{"label":"Exchange through a confidential channel"}]}}},"motif":"Watarase proposes a maritime security partnership."},"watarase-note-regionale":{"hook":"“Mr President, I take the liberty of sending you a note. It is serious, folded in four and lightly perfumed.”","news":"Diplomacy: a discreet exchange between Tokyo and Paris, no comment","scene":{"intro":"The call is brief. The note arrives by a messenger in white gloves, in an unstamped envelope.","nodes":{"n1":{"text":"It concerns the regional situation. I ask you to make enlightened use of it, that is, discreet.","choices":[{"label":"Use the note in all discretion","secret":{"leakNews":"FLASH — A confidential Tokyo note on the region embarrasses Paris"}},{"label":"Share the note with your European partners"},{"label":"Return the note unread"}]},"n2":{"text":"You have my gratitude. In return, I ask only one gesture: a little friendly silence.","choices":[{"label":"Keep silent"},{"label":"Mention the note in your next speech"}]}}},"motif":"Watarase sends you a confidential analysis of the regional situation."},"watarase-appel-puces":{"hook":"“Mr President, chips are today’s oil of yesterday. We have studied how to share them, with elegance.”","news":"Electronic chips: Tokyo and Paris resume talks","motif":"Watarase wants to discuss cooperation on semiconductors.","phone":{"intro":"On the phone, Watarase announces a small parcel is on its way: a rice cake, a card, and a thirty-page file on semiconductors. His voice is sober, each sentence impeccably placed.","nodes":{"n3":{"labels":{"0":"Bow in return, even over the phone","1":"Reply in the Western way, with a “Thank you very much”"}}}}},"watarase-appel-vieillissement":{"hook":"“Mr President, we are ageing, you too. My nurse-robot asked after you, he is very polite.”","news":"Ageing: Tokyo offers Paris health and robotics cooperation","motif":"Watarase proposes cooperation on digital health and robotics.","phone":{"intro":"From a robotics centre, Watarase describes a machine that serves tea to elderly people. It is faster than the staff and better at conversation.","nodes":{"n3":{"text":"A robot greets you in Japanese, in a perfectly courteous synthetic voice. You wonder whether you replied with enough respect.","labels":{"1":"Pretend not to have heard"}}}}},"dovzhenko-promesses-tenues":{"hook":"“Listen to me carefully: I was promised things. I noted them. Do you want me to read you the list, or would you rather guess?”","news":"Dovzhenko loses patience: he demands “deeds, not communiqués”","scene":{"intro":"The line crackles. Dovzhenko does not raise his voice: he lowers it, which is worse.","nodes":{"n1":{"text":"I’m not angry. I’m just tired of being polite. Tell me what is really coming, and when.","choices":[{"label":"Announce a precise delivery schedule"},{"label":"Promise to do your utmost, without figures"},{"label":"Acknowledge the delay and ask for time"}]},"n2":{"text":"Please don’t serve me a speech. A figure is worth more than a rostrum.","choices":[{"label":"Set up monthly, public monitoring"},{"label":"Keep the details confidential"}]}}},"motif":"Dovzhenko reproaches you for unkept promises."},"dovzhenko-munitions-urgence":{"hook":"“My friend, I’m calling for a simple reason: our stocks are emptying faster than our jokes.”","news":"Dovzhenko appeals to Paris for help: ammunition and urgent air defence","scene":{"intro":"At the other end, the hum of a generator. Dovzhenko jokes: “Excuse the noise, it’s the heating.”","nodes":{"n1":{"text":"I need air defence, fast. Not in a quarter. Fast, as in “before the next siren”.","choices":[{"label":"Deliver from your stocks, urgently"},{"label":"Fund an accelerated purchase from European manufacturers"},{"label":"Offer humanitarian aid in the meantime"}]},"n2":{"text":"European opinion also has to hold. Help me keep people with us: that, too, is ammunition.","choices":[{"label":"Speak out to defend this support"},{"label":"Let the experts speak in your place"}]}}},"motif":"Dovzhenko urgently demands ammunition and air defence."},"dovzhenko-visite-paris":{"hook":"“I would like to come and see you in person. Not for a photo: to look in the eye those who foot the bill.”","news":"Dovzhenko announces his intention to come to Paris for a state visit","scene":{"intro":"Dovzhenko laughs briefly: “I’m not coming with three hundred people. I’m coming with one, and a three-hundred-page file.”","nodes":{"n1":{"text":"A short, heavily secured visit, lots of files and very few buffets. Is that all right with you?","choices":[{"label":"Accept the state visit"},{"label":"Propose a remote meeting, simpler"}]},"n2":{"text":"One thing: no gala dinner. I can’t eat foie gras knowing what the soldiers eat.","choices":[{"label":"Replace the gala with a meeting with associations"},{"label":"Keep the dinner, with a moment of solidarity"}]}}},"motif":"Dovzhenko wishes to make a state visit."},"dovzhenko-felicitations":{"hook":"“I’m calling you for a rare reason: good news. So, congratulations. I almost forgot how it’s done.”","news":"Dovzhenko congratulates France: “Good news does you good”","scene":{"intro":"The voice is tired but smiling. Dovzhenko asks for five minutes of normality, not one more.","nodes":{"n1":{"text":"Tell me about it. Something nice, with no drone in it. It will rest me.","choices":[{"label":"Offer him tickets for the next big celebration"},{"label":"Return the compliment and salute his resilience"}]},"n2":{"text":"Thank you. Next good news, I’ll be the one to call you. If that ever happens.","choices":[{"label":"Promise to celebrate it together"},{"label":"Move on to security guarantees"}]}}},"motif":"Dovzhenko congratulates you on your recent success."},"dovzhenko-sommet-garanties":{"hook":"“There’s a summit. I’m going with a suitcase of demands and a front-of-house smile. Will you back me?”","news":"Before the summit: Dovzhenko counts on France to defend his guarantees","scene":{"intro":"Dovzhenko speaks while walking. You hear a door, a corridor, another door, then tea served without ceremony.","nodes":{"n1":{"text":"I want one clear sentence on security guarantees. Not a “we are following the situation closely”.","choices":[{"label":"Carry the request for guarantees to the summit"},{"label":"Stay neutral to spare the hesitant partners"},{"label":"Propose a carefully ambiguous compromise wording"}]},"n2":{"text":"Last point: reconstruction. I want figures, not first-stone ceremonies.","choices":[{"label":"Announce a reconstruction package"},{"label":"Propose a European fund rather than a national commitment"}]}}},"motif":"Dovzhenko asks you to carry his security guarantees to the summit."},"dovzhenko-reconstruction-chantiers":{"hook":"“My friend, one of our towns needs a bridge, a school and a baker. I give you ten minutes to dream big.”","news":"Reconstruction: Dovzhenko asks French companies for a bridge and a school","scene":{"intro":"He describes the town the way one describes a sick relative: precisely, without tears. Then he pulls out a plan scribbled with arrows.","nodes":{"n1":{"text":"I offer you clear projects, with transparent tenders. I don’t like arrangements, I’ve seen enough.","choices":[{"label":"Mobilise your companies on the priority sites"},{"label":"Make the aid conditional on industrial quid pro quos"}]},"n2":{"text":"And for the banks? If your guarantees arrive, it multiplies everything. It’s called “leverage”, I learned the term.","choices":[{"label":"Propose limited and supervised State guarantees"},{"label":"Steer towards European funding"}]}}},"motif":"Dovzhenko wants to involve French companies in the reconstruction."},"dovzhenko-appel-securite":{"hook":"“No speeches, please. Deeds. I’m calling to talk air defence and reconstruction, in that order.”","news":"Dovzhenko presses Paris: security guarantees and reconstruction on the menu","motif":"Dovzhenko wants firm commitments on defence and reconstruction.","phone":{"intro":"Dovzhenko picks up in an office with reinforced windows; his voice is surprisingly firm. He wastes no time: “No speeches, please. Action.”"}},"dovzhenko-appel-agriculture":{"hook":"“The wheat is ripe, so is your market. Let us talk cereals before your farmers send me one more letter.”","news":"Ukrainian cereals: Dovzhenko seeks a balance with Paris","motif":"Dovzhenko wants to discuss wheat and corn imports.","phone":{"intro":"Dovzhenko picks up in the middle of a meal: you hear a knife on bread, bacon and tea. “We talk wheat and security; they are two sides of the same coin.”","nodes":{"n3":{"text":"A siren sounds in the distance, through the receiver. Dovzhenko does not change his tone. You try to do the same, without quite succeeding.","labels":{"0":"Stay on the line","1":"Ask him to head for the shelter"}}}}}}`),t={motifs:e};export{t as default,e as motifs};
